  var st=AU.running?'<span class="tag warn">läuft · '+AU.done+' / '+AU.total+'</span>':AU.end?'<span class="muted">Stand '+esc(new Date(AU.end).toLocaleString("de-AT"))+' · '+AU.products+' Produkte</span>':'<span class="muted">noch nicht geprüft</span>';
  var k=function(n,l,s){ return '<div><span>'+l+'</span><b class="'+(n?"mg-w":"mg-g")+'">'+n+'</b><span>'+s+'</span></div>'; };
  var head='<section class="panel"><div class="panel-h"><h2>Sortiments-Prüfung</h2>'+st+(AU.running?'':'<button class="btn" data-act="aurun">Prüfung starten</button>')+'</div><div class="panel-b"><p class="muted small" style="margin:0 0 10px">Gleicht jedes Print.com-Produkt mit dem Shop ab: wählbare Optionen, Preis der Startausführung, Formate und Bezeichnungen. Hat die Startausführung keinen Preis, sucht die Prüfung eine Alternative (Auflage, Option, Farbe/Größe) und nimmt sie als neue Startausführung; ist ein Produkt gar nicht bestellbar oder nicht nach Österreich lieferbar, wird es ausgeblendet (nie deine Kernprodukte, unter „Sortiment“ wieder einschaltbar). Kundenanfragen haben Vorrang.</p><div class="mg-k">'+
    k(AU.noPrice||0,"Ohne Preis","Startausführung – davon "+(AU.fixedStart||0)+" ersetzt, "+(AU.hidden||0)+" ausgeblendet"+(AU.shown?", "+AU.shown+" wieder eingeblendet":""))+k(AU.missing||0,"Optionen fehlen","bei Print.com wählbar, im Shop nicht")+k(AU.labels||0,"Bezeichnungen","Code, Fremdwort, Leerzeichen")+k(AU.noDims||0,"Formate ohne Maße","Endformat unbekannt")+'</div></div></section>';
  var sec=function(t,l,fn){ return l.length?'<section class="panel"><div class="panel-h"><h2>'+t+'</h2><span class="muted">'+l.length+'</span></div><div class="panel-b"><ul class="au-l">'+l.slice(0,150).map(fn).join("")+'</ul>'+(l.length>150?'<p class="muted small">… und '+(l.length-150)+' weitere</p>':'')+'</div></section>':''; };
