  var proof=function(cls,lab){ return '<button class="btn'+(cls?" "+cls:"")+'" data-act="prproof:'+id+'">'+(lab||"Zur Freigabe senden")+'</button>'; };
  var upl='<label class="btn" title="Korrigierte PDF hochladen – wird wie beim Kunden geprüft, die alte Datei bleibt im Verlauf">Datei selbst hochladen<input type="file" accept="application/pdf,.pdf" hidden data-prrepl="'+id+'"></label>';
  var n={tone:"info",ic:"→",k:"Nächster Schritt",t:"",s:"",a:"",b:"",used:""};
