F.prReject=function(id,info,quiet){ var o=ord(id,info);
  F.modal('<h2 style="font-size:19px">Bestellung '+esc(o.nr||"")+' ablehnen</h2><label class="fl">Grund (geht an den Kunden)<textarea class="f" id="prRe" rows="3" placeholder="z. B. Text liegt im Beschnitt, bitte neu hochladen"></textarea></label>'+(o.paymentStatus==="paid"?'<label class="small"><input type="checkbox" id="prRf" checked> Betrag über Mollie erstatten ('+eur(o.gross)+')</label>':'')+'<div class="foot"><span></span><span class="row"><button class="btn" data-closemodal>Abbrechen</button><button class="btn danger" id="prRok">Ablehnen</button></span></div>',"narrow");
  document.getElementById("prRok").onclick=function(){ var r=document.getElementById("prRe").value, rf=document.getElementById("prRf"); F.closeModal(); op({op:"reject",id:id,reason:r,refund:rf?rf.checked:false},"Abgelehnt"+(rf&&rf.checked?" und Erstattung veranlasst":""),quiet); }; };
/* Stornieren ohne Mail (Simon 12.11.2026, z. B. telefonisch vereinbart): wie Ablehnen, aber der Kunde wird nicht angeschrieben */
F.action("prstorno",function(id){ var o=ord(id); if(!o) return;
  F.modal('<h2 style="font-size:19px">Bestellung '+esc(o.nr||"")+' stornieren</h2><p class="muted">Der Kunde bekommt <b>keine Mail</b> – z. B. wenn du es schon telefonisch ausgemacht hast. Ein Rechnungsentwurf wird gelöscht.</p><label class="fl">Notiz (nur intern, optional)<input class="f" id="prSn" placeholder="z. B. telefonisch storniert"></label>'+(o.paymentStatus==="paid"?'<label class="small"><input type="checkbox" id="prSf" checked> Betrag über Mollie erstatten ('+eur(o.gross)+')</label>':'')+'<div class="foot"><span></span><span class="row"><button class="btn" data-closemodal>Abbrechen</button><button class="btn danger" id="prSok">Stornieren</button></span></div>',"narrow");
  document.getElementById("prSok").onclick=function(){ var n=document.getElementById("prSn").value, rf=document.getElementById("prSf"); F.closeModal(); op({op:"reject",id:id,reason:n,refund:rf?rf.checked:false,silent:true},"Storniert – ohne Mail an den Kunden"); }; });
