/* Liefertermin ändern, solange der Auftrag in Prüfung ist (Simon 15.11.2026) – Tage frisch von Print.com, Versandkosten je Tag; geht beim Bestellen als Wunsch-Liefertag mit */
F.action("prwish",function(id){
  F.modal('<h2 style="font-size:19px">Liefertermin ändern</h2><p class="muted" style="margin:0">Lade mögliche Liefertage von Print.com (alle Lieferstufen) …</p>',"narrow");
  F.api("/admin/api/print/op",{body:{confirm:true,op:"days",id:id}}).then(function(j){
    if(!j||!j.ok){ F.closeModal(); F.toast((j&&j.error)||"Liefertage konnten nicht geladen werden",true); return; }
    var wd=["So","Mo","Di","Mi","Do","Fr","Sa"], fmt=function(d){ var t=new Date(d+"T12:00:00"); return wd[t.getDay()]+", "+de(d); }, biz=j.business;
    var ex=function(x){ return biz?x.extraNet:x.extraGross; };
    var rows=j.days.map(function(x){ var bd=Math.round((x.buy-j.buyNow)*100)/100;
      return '<button type="button" class="btn'+(x.current?' primary':'')+'" data-d="'+esc(x.d)+'" style="justify-content:space-between;width:100%;text-align:left"'+(x.current?' disabled':'')+'><span><b>'+fmt(x.d)+'</b>'+(x.u!=="standard"?' <span class="pr-chip warn">'+esc(x.urgency)+'</span>':'')+(x.current?' · aktuell':'')+'<br><span class="muted small">Einkauf '+(Math.abs(bd)<0.005?'gleich':(bd>0?'+':'−')+eur(Math.abs(bd)))+'</span></span><b>'+(ex(x)>0.004?'+'+eur(ex(x))+' <span class="muted small" style="font-weight:400">Kunde'+(biz?' netto':'')+'</span>':'<span class="muted small">kein Aufpreis</span>')+'</b></button>'; }).join("");
    /* Termin früher ohne Aufpreis vorgezogen (z. B. Expressversand): Differenz zu einem günstigeren Tag nachverrechnen, Termin bleibt (Simon 16.11.2026) */
    var cur=j.days.filter(function(x){ return x.current; })[0], cheaper=cur?j.days.filter(function(x){ return x.gross<cur.gross-0.004; }):[], late="";
    if(cur&&cheaper.length){ late='<div class="prd-bf" style="margin-top:12px"><span><b>Aufpreis für den aktuellen Termin nachverrechnen</b> – der Termin bleibt, der Kunde zahlt die Differenz zu:'+(j.charged>0.004?' <span class="bad-t">(schon verrechnet: '+eur(j.charged)+')</span>':'')+'</span><span class="row" style="gap:8px;flex-wrap:wrap"><select id="prWFrom" style="width:auto">'+cheaper.map(function(x,i){ var dd=Math.round((biz?cur.net-x.net:cur.gross-x.gross)*100)/100; return '<option value="'+esc(x.d)+'"'+(i===0?' selected':'')+'>'+fmt(x.d)+' · +'+eur(dd)+(biz?' netto':'')+'</option>'; }).join("")+'</select><button type="button" class="btn primary" id="prWLate">'+(j.inDraft?'In Rechnungsentwurf übernehmen':'Rechnung erstellen &amp; senden')+'</button></span></div>'; }
    F.modal('<h2 style="font-size:19px">Liefertermin ändern</h2><p class="muted" style="margin:0">Aktuell: <b>'+(j.current?fmt(j.current):"–")+'</b>'+(j.current&&!j.curOk?' <span class="bad-t">(nicht mehr möglich)</span>':'')+'. Der neue Tag geht beim Bestellen als Wunsch-Liefertag an Print.com. '+(j.inDraft?'Ein Aufpreis kommt in den noch offenen Rechnungsentwurf.':'Bei Aufpreis wird eine eigene Rechnung erstellt und sofort an den Kunden gesendet.')+'</p><div id="prWD" style="display:grid;gap:6px;margin-top:12px;max-height:55vh;overflow:auto">'+(rows||'<div class="muted">Keine Liefertage verfügbar.</div>')+'</div>'+late+'<div class="foot"><span></span><button class="btn" data-closemodal>Abbrechen</button></div>',"narrow");
    var lb=document.getElementById("prWLate"); if(lb) lb.onclick=function(){ var from=document.getElementById("prWFrom").value; F.closeModal(); F.toast("Bitte warten …");
      F.api("/admin/api/print/op",{body:{confirm:true,op:"wish",id:id,date:cur.d,from:from,charge:true}}).then(function(r){ if(!r||!r.ok){ F.toast((r&&r.error)||"Fehler",true); return; } F.toast(r.warn||(j.inDraft?"Aufpreis in den Rechnungsentwurf übernommen":"Rechnung für den Aufpreis gesendet"),!!r.warn); load(true); openOrder(id); }); };
    var box=document.getElementById("prWD"); if(box) box.addEventListener("click",function(e){ var b=e.target.closest("button[data-d]"); if(!b) return; var d=b.getAttribute("data-d"), x=j.days.filter(function(y){ return y.d===d; })[0]; if(!x) return;
      var go=function(charge){ F.closeModal(); F.toast("Bitte warten …"); F.api("/admin/api/print/op",{body:{confirm:true,op:"wish",id:id,date:d,charge:charge}}).then(function(r){ if(!r||!r.ok){ F.toast((r&&r.error)||"Fehler",true); return; } F.toast(r.warn||("Liefertermin geändert: "+fmt(d)+(charge?(j.inDraft?" · Aufpreis im Rechnungsentwurf":" · Rechnung gesendet"):"")),!!r.warn); load(true); openOrder(id); }); };
      if(!(ex(x)>0.004)){ go(false); return; }
      F.modal('<h2 style="font-size:19px">Aufpreis verrechnen?</h2><p style="margin:0">Neuer Termin <b>'+fmt(d)+'</b>'+(x.u!=="standard"?' ('+esc(x.urgency)+')':'')+'. Der Kunde zahlt <b>'+eur(x.extraGross)+'</b> brutto'+(biz?' ('+eur(x.extraNet)+' netto)':'')+' mehr.</p><p class="muted small" style="margin:8px 0 0">'+(j.inDraft?'„Mit Rechnung“ nimmt den Aufpreis in den noch offenen Rechnungsentwurf auf.':'„Mit Rechnung“ erstellt eine eigene Rechnung für den Aufpreis und sendet sie sofort per Mail an den Kunden.')+'</p><div class="foot"><button class="btn" data-closemodal>Abbrechen</button><span class="row"><button class="btn" id="prWNo">Ohne Aufpreis</button><button class="btn primary" id="prWYes">Mit Rechnung ändern</button></span></div>',"narrow");
      document.getElementById("prWYes").onclick=function(){ go(true); }; document.getElementById("prWNo").onclick=function(){ go(false); };
    });
  });
});
