function soFilter(){ var q=SOQ.trim().toLowerCase(); document.querySelectorAll(".pr-so").forEach(function(r){ r.hidden=!!q&&r.getAttribute("data-q").indexOf(q)<0; }); if(q) document.querySelectorAll(".pr-sub").forEach(function(s){ s.hidden=!s.querySelector(".pr-so:not([hidden])"); }); else document.querySelectorAll(".pr-sub").forEach(function(s){ s.hidden=false; });
  document.querySelectorAll(".pr-cat").forEach(function(d){ if(q){ var any=!!d.querySelector(".pr-so:not([hidden])"); d.hidden=!any; d.open=any; } else { d.hidden=false; d.open=!!SOOPEN[d.getAttribute("data-somain")]; } }); }
F.listen("input","#prSoQ",function(el){ SOQ=el.value; clearTimeout(el._d); el._d=setTimeout(soFilter,150); });
F.listen("click","[data-somain] > summary",function(el){ SOOPEN[el.parentNode.getAttribute("data-somain")]=!el.parentNode.open; });
