F.listen("change","[data-soset]",function(el){ soOp({op:"set",sku:el.getAttribute("data-soset"),on:el.checked},el.checked?"Im Shop":"Aus dem Shop genommen"); });
F.listen("change","[data-soov]",function(el){ soOp({op:"override",sku:el.getAttribute("data-soov"),cat:el.value},"Kategorie gespeichert"); });
F.action("prsoload",function(){ SO=null; F.render(); });
F.action("prsoref",function(){ F.toast("Lade Sortiment von Print.com …"); soOp({op:"refresh"},"Sortiment aktualisiert – Kategorien werden im Hintergrund eingelesen"); });
F.action("prsoall",function(v){ var p=v.split("|"); F.confirm((p[1]==="1"?"Alle Produkte dieser Kategorie einzeln freischalten?":"Alle Produkte dieser Kategorie einzeln aus dem Shop nehmen?"),"Ja",function(){ soOp({op:"catAll",cat:p[0],on:p[1]==="1"},"Gespeichert"); }); });
