function fbStars(r){ return '<span style="color:var(--warn);letter-spacing:1px" aria-label="'+r+' von 5 Sternen">'+"★★★★★".slice(0,r)+'<span style="opacity:.3">'+"★★★★★".slice(r)+'</span></span>'; }
