  var top='<div style="display:flex;gap:12px;flex-wrap:wrap;margin:0 0 14px">'+card("Bestellvorgang (direkt nach der Bestellung)",FB.order)+card("Drucksachen (nach der Lieferung)",FB.product,FB.asked+" per Mail gefragt")+srcCard+'</div>'+
    (FB.reviewUrl?'<p class="muted" style="font-size:12.5px;margin:-4px 0 14px">Nach dem Absenden sehen alle Kund:innen – unabhängig von den Sternen – „Auch auf Google bewerten“ (<a href="'+esc(FB.reviewUrl)+'" target="_blank" rel="noopener">Link prüfen</a>).</p>'
      :'<div class="notice" style="margin:0 0 14px">Kein Google-Bewertungslink hinterlegt – der Knopf „Auch auf Google bewerten“ bleibt ausgeblendet. Railway-Variable <b>PRINT_GOOGLE_REVIEW_URL</b> setzen (Link aus dem Google-Unternehmensprofil → „Nach Rezensionen fragen“).</div>');
